import{_ as s,o as t,c as a,ax as i}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Authenticate","description":"Pair the Developer Studio CLI with your community using a pairing code, check the current session, and log out.","frontmatter":{"description":"Pair the Developer Studio CLI with your community using a pairing code, check the current session, and log out."},"headers":[],"relativePath":"cli/authenticate.md","filePath":"cli/authenticate.md"}'),n={name:"cli/authenticate.md"};function o(r,e,d,h,c,l){return t(),a("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/authenticate.md for this page in Markdown format</div><h1 id="authenticate" tabindex="-1">Authenticate <a class="header-anchor" href="#authenticate" aria-label="Permalink to &quot;Authenticate&quot;">​</a></h1><p>Use this guide when you need to pair <code>gsds</code> with your community for the first time, refresh an expired session, confirm which tenant you are paired with, or sign out of a shared machine.</p><h2 id="pair-a-session" tabindex="-1">Pair a session <a class="header-anchor" href="#pair-a-session" aria-label="Permalink to &quot;Pair a session&quot;">​</a></h2><p>Open the <strong>Connect CLI</strong> flow inside your community and copy the <strong>pairing code</strong>. Then run:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PAIRING-CODE-FROM-COMMUNITY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pairing codes have a <strong>2-minute</strong> time-to-live, so redeem them immediately. If the code expires, mint a fresh one from your community and try again.</p><p>On success, <code>gsds</code> stores a tenant-scoped session token that is valid for approximately <strong>8 hours</strong>.</p><h2 id="check-the-current-session" tabindex="-1">Check the current session <a class="header-anchor" href="#check-the-current-session" aria-label="Permalink to &quot;Check the current session&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Reports which tenant the current session is bound to and whether it is still valid. Use this first whenever you see a <code>401</code> from <code>gsds preview</code> or <code>gsds connector test</code>.</p><h2 id="refresh-an-expired-session" tabindex="-1">Refresh an expired session <a class="header-anchor" href="#refresh-an-expired-session" aria-label="Permalink to &quot;Refresh an expired session&quot;">​</a></h2><p>There is no refresh flow — when the ~8-hour token expires, mint a new pairing code from your community and redeem it:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NEW-PAIRING-CODE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="log-out" tabindex="-1">Log out <a class="header-anchor" href="#log-out" aria-label="Permalink to &quot;Log out&quot;">​</a></h2><p>Clear the stored session:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logout</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Run this before handing a shared workstation to another developer, or when switching between tenants.</p><h2 id="where-the-session-is-stored" tabindex="-1">Where the session is stored <a class="header-anchor" href="#where-the-session-is-stored" aria-label="Permalink to &quot;Where the session is stored&quot;">​</a></h2><p><code>gsds</code> writes the session token to your OS keychain — macOS Keychain, Windows Credential Store, or Linux Secret Service / keyutils — under service <code>gainsight-developer-studio-cli</code>, account <code>default</code>.</p><p>If the keychain is unavailable (no supported provider, headless CI, or a keychain error), <code>gsds</code> falls back to <code>~/.config/gsds/credentials.json</code> at file mode <code>0600</code> and prints a one-time warning on stderr. You can force the file fallback by setting <code>GSDS_DISABLE_KEYCHAIN=1</code>.</p><h2 id="commands-that-require-a-session" tabindex="-1">Commands that require a session <a class="header-anchor" href="#commands-that-require-a-session" aria-label="Permalink to &quot;Commands that require a session&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Why it needs a session</th></tr></thead><tbody><tr><td><code>gsds preview</code></td><td>Registers a preview session with your community so local widgets appear in the picker</td></tr><tr><td><code>gsds connector test</code></td><td>Runs against the paired tenant</td></tr></tbody></table><p>Every other command works without a session.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Test a Connector against the paired tenant in <a href="./test-connectors.html">Test Connectors</a></li><li>Run <code>gsds</code> unattended in CI or from an AI agent with <a href="./automate-with-ci-and-ai.html">Automate with CI and AI</a></li><li>Look up flags for the login commands in the <a href="./reference/commands.html">Command reference</a></li></ul>',26)])])}const m=s(n,[["render",o]]);export{u as __pageData,m as default};
